scripts.script:
const dc = 17;
const qimanMod = Math.floor(actor.system.skills.qiman.total || 0);
const roll = await new Roll("1d20 + @mod", {mod: qimanMod}).evaluate();
if (game.dice3d) game.dice3d.showForRoll(roll, game.user, true);

await roll.toMessage({ speaker: ChatMessage.getSpeaker({actor: actor}), flavor: `断舌诀(小成) - 欺瞒检定 (DC ${dc})` });

if (roll.total >= dc) {
    const eff = thisItem.effects.getName("断舌诀-阴冷").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    eff.duration = { rounds: 1 };
    foundry.utils.setProperty(eff, "flags.xjzl-system.hitCount", 0);

    await game.xjzl.api.effects.addEffect(actor, eff);
    actor.showFloatyText("气息阴冷", { fill: "#8e44ad" });
}

const dc = 13;
const qimanMod = Math.floor(actor.system.skills.qiman.total || 0);
const roll = await new Roll("1d20 + @mod", {mod: qimanMod}).evaluate();
if (game.dice3d) game.dice3d.showForRoll(roll, game.user, true);

await roll.toMessage({ speaker: ChatMessage.getSpeaker({actor: actor}), flavor: `断舌诀(圆满) - 欺瞒检定 (DC ${dc})` });

if (roll.total >= dc) {
    const eff = thisItem.effects.getName("断舌诀-阴冷").toObject();
    delete eff._id;
    eff.origin = thisItem.uuid;
    eff.duration = { rounds: 1 };
    foundry.utils.setProperty(eff, "flags.xjzl-system.hitCount", 0);

    await game.xjzl.api.effects.addEffect(actor, eff);
    actor.showFloatyText("气息阴冷", { fill: "#8e44ad" });
}

if (!args.isHit || !args.target || args.actionType !== "attack") return;

let count = thisEffect.getFlag("xjzl-system", "hitCount") || 0;
count += 1;
await thisEffect.setFlag("xjzl-system", "hitCount", count);

let statusToApply = "";
let statusName = "";

if (count === 1) { statusToApply = "youyu"; statusName = "犹豫"; }
else if (count === 2) { statusToApply = "yudun"; statusName = "愚钝"; }
else if (count === 3) { statusToApply = "fatigue"; statusName = "疲劳"; }

if (statusToApply) {
    await game.xjzl.api.effects.addEffect(args.target, { id: statusToApply, duration: { rounds: 1 } });
    actor.showFloatyText(`施加 ${statusName}`, { fill: "#8e44ad", fontSize: 28 });
}
